insert into public.buildpulse_private_settings(key,value,updated_at) select 'ai_evaluation_scheduler_secret',encode(gen_random_bytes(32),'hex'),now() where not exists(select 1 from public.buildpulse_private_settings where key='ai_evaluation_scheduler_secret');
select cron.schedule('buildpulse-ai-evaluations-db','11 4 * * 0',$$select net.http_post(url := 'https://www.buildpulse.news/api/cron/ai-evaluations',headers := jsonb_build_object('Content-Type','application/json','x-buildpulse-scheduler-secret',(select value from public.buildpulse_private_settings where key='ai_evaluation_scheduler_secret')),body := '{}'::jsonb);$$);
